-- Case studies for five /work pages (approved). Run once in the Supabase SQL editor.
begin;
insert into public.media_migration_backup (tbl,row_id,row_data) select 'projects_case_study', id::text, to_jsonb(p) from public.projects p where lower(slug) in ('tmm-artworks','orcbardwmg','haziellastlight-mtgproxy','ashoakriver','fs-erasedrune');
update public.projects set hook = $cs$Fan art for a D&D campaign, from character portraits to MTG commanders$cs$, seo_description = $cs$Seven fan-art character illustrations for The Midnight Misfits D&D campaign, later reimagined as custom Magic: The Gathering commander cards.$cs$, narrative = $cs${"context": "This one wasn't a commission. The Midnight Misfits is a Dungeons & Dragons campaign run by Dungeon Master Jeremy Siregar, with a cast of public figures from very different worlds, from the kitchen to the comedy stage. I followed the campaign as a fan and wanted to give something back: a full set of character art for the party, drawn the way I see them at the table.", "move": "The challenge I set myself was likeness. Every character had to stay recognizable as the real person playing them, while looking like they truly belong in a high-fantasy world. The party is called \"Misfits\" for a reason, so the art couldn't feel like polished heroes on a poster. It had to feel chaotic but still balanced as a set.", "build": "Seven illustrations in about two weeks, drawn in Clip Studio Paint on an iPad Pro.\n- Shape language did most of the work: sharp, angular silhouettes for the chaotic characters, heavy grounded blocks for the tanks and frontliners.\n- Costumes carry the story. Scuffed armor and patched gear say these are survivors, not parade knights.\n- A \"midnight\" palette ties the set together: deep blues and purples, cut with warm, dangerous highlights.\n\nOnce the set was done, I pushed it one step further on my own: each character redrawn as a Magic: The Gathering commander, as if the party had been printed into a deck.", "result": "The campaign shared the artwork on its channels and shouted me out by name as the artist supporting the campaign. For me, the set became a proof of what a party commission can look like: consistent style, distinct characters, and a format (MTG cards) that players can actually use at the table.\n\nWant your own party drawn like this? Commission it here: https://mjfird.com/services/dnd-character"}$cs$::jsonb, client = $cs$The Midnight Misfits (fan art)$cs$, role = $cs$Illustrator$cs$ where lower(slug) = 'tmm-artworks';
update public.projects set hook = $cs$A character sample for West Marches Games' landing page$cs$, seo_description = $cs$Orc Bard character design for West Marches Games: a fantasy frontliner with a battle axe, shield and a performer's swagger, drawn as a landing-page sample.$cs$, narrative = $cs${"context": "West Marches Games needed a character sample for their landing page at westmarches.games. The archetype was classic, but with a twist: an orc bard, armed with a battle axe and a shield. The art had to show visitors, at a glance, the kind of characters they could bring to a West Marches table.", "move": "An orc bard sits between two very different fantasies. On one side, the brute strength of a frontline fighter. On the other, the charm and showmanship of a performer. The design had to carry both without one cancelling the other: a character you'd trust to hold the line and also to start the tavern singing afterwards.", "build": "- Silhouette first: a broad, heavy frame and a big shield to sell the frontliner, with an open, confident stance that reads as a performer rather than a brute.\n- Gear tells the double life: practical battle-worn armor, with flourishes and details that belong to a bard.\n- The sketch went through three or four rounds of feedback before line art, which is where a design like this is cheapest to get right.\n- Drawn and colored in Clip Studio Paint on an iPad Pro, in my cel-shaded style, so the character reads cleanly at landing-page size.\n- Color stays earthy and grounded, so the orc feels like he belongs to the same world as the rest of the site, not pasted on top of it.", "result": "The finished Orc Bard is used as a character sample on the West Marches Games landing page, the first thing new players see when they visit.\n\nIt's also a good example of what working with a game company looks like with me: a clear brief, an early sketch stage where the big decisions happen, and art sized and shaped for where it will live.\n\nNeed character art for your game, campaign or landing page? Start here: https://mjfird.com/services/dnd-character"}$cs$::jsonb where lower(slug) = 'orcbardwmg';
update public.projects set hook = $cs$A VTuber avatar, compleated into an Atraxa proxy$cs$, seo_description = $cs$Custom MTG proxy art for Atraxa, Grand Unifier, starring VTuber Haziel Lastlight in Phyrexian form: porcelain mask, autopsy scar and purple-magenta glow.$cs$, narrative = $cs${"context": "Haziel Lastlight wanted to play her own VTuber avatar as Atraxa, Grand Unifier, in Phyrexian, \"compleated\" form. She gave me free rein on the design, with one firm rule: her face had to stay recognizable, even with the lower half hidden behind a porcelain-doll mask, and her autopsy scar had to be worked into it.", "move": "Two styles had to meet in the middle. Her avatar is clean and anime; Phyrexian design is all metal, sinew and body horror. The plan was to keep her face and colors as the anchor, then let the Phyrexian elements grow around them: the mask, the scar, the alien plating. A purple gradient background with magenta highlights and ambient light gives the whole piece a quiet, unsettling glow.", "build": "- The face came first. Everything else was designed around keeping it readable, especially where the porcelain mask meets her skin.\n- The hardest part was the detail and texture work: porcelain, metal and fabric all need to read differently, yet still sit inside an anime cel-shaded render.\n- The scar runs through the mask instead of stopping at it, so it feels like part of her, not a sticker on top.\n- I kept the render in the same anime cel-shading as her avatar, so the piece still feels like her own model, just pulled into Phyrexia.\n- About five days from sketch to final, in Clip Studio Paint on an iPad Pro.", "result": "A proxy of Atraxa, Grand Unifier that is unmistakably Haziel. She shared the finished art across all of her social accounts, which is the best review a piece like this can get: the person it's about wanted everyone to see it.\n\nIt shows the kind of brief I enjoy most: \"make it yours, but keep it me\". Have a character you want on a card? https://mjfird.com/services/custom-mtg"}$cs$::jsonb where lower(slug) = 'haziellastlight-mtgproxy';
update public.projects set hook = $cs$Custom MTG proxy for a returning client: Sisay, reimagined$cs$, seo_description = $cs$Ash Oakriver, Half-Fae Gangster: a custom MTG proxy of Sisay, Weatherlight Captain, with a storm background. One of three cards for a returning client.$cs$, narrative = $cs${"context": "Nax24 came to me through VGen with a proxy for Sisay, Weatherlight Captain, starring their own character, Ash Oakriver. The pose and expression were set by the client's references, and the background had to be a storm, lightning and all. The card got its own name and flavor text: \"Ash Oakriver, Half-Fae Gangster\". \"I will become queen for my friends, for my city, and for my papa!\"", "move": "A commander card has to work at two sizes: as a full illustration, and squeezed into a card frame on the table. The storm gave me a strong, dark backdrop to push Ash forward, with the lightning used as a natural light source that sculpts the character and leads the eye to her face.", "build": "- Pose and expression followed the client's references closely, so the character felt like theirs.\n- The flavor text set the tone: proud, a little dangerous, loyal to her people. That's the attitude the pose and lighting lean into.\n- The storm background was kept simple in shape and dramatic in value, so the figure still reads when the art shrinks to card size.\n- Drawn and rendered in Clip Studio Paint on an iPad Pro, then laid out as a finished card in Card Conjurer with the custom name and flavor text.\n\nHere is the process, from sketch to finished card:\n\nhttps://youtu.be/iop5-QhHc-E", "result": "Ash Oakriver was the start of a run. Nax24 came back every week or two for more cards, including Contest for the Throne and Jack Hefetz, because the art style fit what they wanted for their deck.\n\nThat kind of repeat work is exactly what I aim for: once a client's style is set, every new card builds on the last one. Want your own commander? https://mjfird.com/services/custom-mtg"}$cs$::jsonb where lower(slug) = 'ashoakriver';
update public.projects set hook = $cs$The Erased Rune: my debut dark-fantasy novel, written and illustrated by me$cs$, seo_description = $cs$Friedenia Saga: The Erased Rune, a 2025 dark-fantasy novel written and illustrated by M.J. Fird, the first piece of an original IP heading toward a TCG.$cs$, narrative = $cs${"context": "Friedenia Saga is my own world, and The Erased Rune is its first book, published in 2025 with the support of One Peach Media. There was no client here: just a world that had lived in my head for years and needed to become something people could hold.", "move": "I wanted to write a dark fantasy that pushes back against absolute destiny, and to build a world big enough to hold more than one story. The protagonist, Reve Elvarin, doesn't only fight enemies; he fights the version of history everyone else accepts. When he awakens the Eighth Rune, the forbidden symbol of Free Will, he sets off a chain reaction against the Order of Balance and the world it holds together.", "build": "I wrote the novel and drew all of its artwork: the cover and the illustrations inside. Like my commission work, the art is made in Clip Studio Paint on an iPad Pro. I wasn't alone on the book: Dani Setiadi helped with the cover layout, and Airy Ananta edited the text. Writing and illustrating together let the words and the pictures shape each other, so the characters look the way the story describes them.", "result": "I brought the book to Semarang IP Fest 2026, my first pop-up art market, and every copy I brought sold out. It's now available on Tokopedia: https://tk.tokopedia.com/ZSseBboVr/\n\nFor me it's only the beginning. Friedenia is meant to be a whole ecosystem, not a single story. The clash between the Order of Balance and the Freeborn Flame carries on beyond this book: a Trading Card Game is already in the prototype stage, and more lore is on the way. Selling out a small first print run at my first market told me the world has readers waiting for it.\n\nRead about that day at the market: https://mjfird.com/blog/semarang-ip-fest-2026"}$cs$::jsonb where lower(slug) = 'fs-erasedrune';
commit;
